using TracezillaShopify.Workflows;
public sealed class SynchronizeInventoryTests{[Fact]public async Task PreviewsWithoutWriting(){var target=new Target();var result=await new SynchronizeInventory(new Source(),target).RunAsync("gid://1",2);var json=System.Text.Json.JsonSerializer.Serialize(result);Assert.Contains("would_update",json);Assert.Empty(target.Writes);}private sealed class Source:IInventorySource{public Task<IReadOnlyList<TracezillaInventory>> ReadWarehouseAsync(int n)=>Task.FromResult<IReadOnlyList<TracezillaInventory>>([new("BAN-1",2,1,2,1)]);}private sealed class Target:IInventoryTarget{public List<int> Writes=[];public Task<IReadOnlyDictionary<string,ShopifyInventory>> ReadAtLocationAsync(string id)=>Task.FromResult<IReadOnlyDictionary<string,ShopifyInventory>>(new Dictionary<string,ShopifyInventory>{{"BAN-1",new("BAN-1","1",true,3)}});public Task SetAvailableAsync(ShopifyInventory item,int quantity,string location){Writes.Add(quantity);return Task.CompletedTask;}}}
